"""Build public history from recoverable documentation and actual release commits."""
import json,re,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1]
def git(*args):return subprocess.check_output(['git',*args],cwd=root,text=True,stderr=subprocess.DEVNULL)
readme=(root/'README.md').read_text();entries={}
# Explicit historical headings and version paragraphs, preserved in the imported README.
markers=[]
for m in re.finditer(r'(?m)^#{1,3}[^\n]*(?:\bv(\d+)\b|Edition (\d+)\b)[^\n]*|^Version (\d+)\b[^\n]*',readme):
 n=int(next(v for v in m.groups() if v));markers.append((m.start(),m.end(),n,m.group()))
for i,(start,end,n,title) in enumerate(markers):
 stop=min([pos for pos,_,_,_ in markers if pos>start]+[len(readme)])
 body=readme[end:stop].strip() if title.startswith('#') else readme[start:stop].strip()
 # Keep the first descriptive paragraph, without tests or claims from later unnumbered revisions.
 paragraph=next((p for p in re.split(r'\n\s*\n',body) if p.strip() and not p.startswith('Validation:')),'')
 paragraph=re.sub(r'\s+',' ',paragraph).strip('- ')
 if paragraph:entries[n]={'legacyVersion':n,'version':f'v0.0.{n}','title':re.sub(r'^#+\s*|^Version \d+\s*','',title).strip()[:120] if title.startswith('#') else f'World and gameplay update {n}','changes':[paragraph],'source':{'path':'README.md','kind':'historical documentation'}}
# v14 and v6 are explicitly identified within otherwise unnumbered sections.
for n,heading in [(14,'# The Zero Gravity - Web — Reference HUD / Model Rework'),(6,'# The Zero Gravity - Web — Surface Edition 6')]:
 start=readme.index(heading)+len(heading);text=readme[start:].strip().split('\n\n')[0]
 entries[n]={'legacyVersion':n,'version':f'v0.0.{n}','title':'Reference HUD and Blender models' if n==14 else 'Surface launch and landing','changes':[re.sub(r'\s+',' ',text)],'source':{'path':'README.md','kind':'historical documentation'}}
# Cache versions 91 remained unchanged through several named releases: prefer the explicit commit version.
for sha in git('rev-list','--reverse','HEAD').splitlines():
 subject=git('show','-s','--format=%s',sha).strip()
 if subject.startswith('Merge '):continue
 explicit=re.search(r'\bv(\d+)\b',subject)
 try:n=int(json.loads(git('show',sha+':public/source-manifest.json'))['version'])
 except (subprocess.CalledProcessError,ValueError,KeyError):continue
 if explicit and int(explicit.group(1))>=60:n=int(explicit.group(1))
 # The restore commit calls its archive v61, but its source manifest and README are v59.
 if sha.startswith('ef953e7'):n=59
 # This patch mentions the stale boot version it fixed, not its release number.
 if sha.startswith('07faad9'):n=102
 if n<59:continue
 date=git('show','-s','--format=%cs',sha).strip()
 description=re.sub(r'\s*\(v\d+\)|^v\d+:\s*','',subject)
 entry=entries.setdefault(n,{'legacyVersion':n,'version':f'v0.0.{n}','title':description,'changes':[]})
 if n==59 and entry['changes']:continue
 entry.update({'title':description,'date':date,'source':{'commit':sha,'kind':'Git history'}})
 if description not in entry['changes']:entry['changes'].append(description)
entries[102]={'legacyVersion':102,'version':'v0.0.102','date':'2026-10-27','title':'Update history, full game screenshots and legacy cleanup','changes':['Added the Update Logs menu with recoverable release history and consistent semantic version labels.','Screenshots now capture the game viewport with HUD, controls, chat and open menus.','Removed legacy installation overlays and generated asteroid/hash labels across world, sky and map paths.','Corrected the HTML entrypoint still loading the legacy v0.0.100 boot module; startup now reads fresh release metadata and imports the matching game revision.'],'source':{'kind':'current release'}}
entries[103]={'legacyVersion':103,'version':'v0.0.103','date':'2026-10-27','title':'I polished the release and added phone notification support','changes':['I centered and cleaned up Update Logs on phones and computers.','I added distance fog to hide terrain edges on airless worlds.','I fixed the unnecessary exploration error in the account menu.','I removed saved places from More. Entering free camera now costs 100 RC.','I added separate phone notification settings: global chat is off by default; party chats and friend requests are on.','I added a pending friend-request count and message-style request sounds. Closed-game notifications require the push backend and browser permission.'],'source':{'kind':'current release'}}
entries[104]={'legacyVersion': 104, 'version': 'v0.0.104', 'date': '2026-10-27', 'title': 'I fixed villages, ship collisions and item sounds', 'changes': ['I added a village within a short walk of the launch pad and kept existing village changes saved.', 'I removed the repeated explosion sound on obstacle contact. The ship now guides itself to nearby clear ground.', 'I fixed held resources turning with the world instead of staying in the same position in my hand.', 'I replaced the TNT fuse hiss with a short beep every second before the explosion.', 'I added TNT damage to ships and a replacement at the current world’s launch pad, while keeping on-foot players in place.', 'I matched the launch tower’s collision to its shaft, platforms and arm.', 'I stopped menu opening and button clicks from playing the same UI sound twice.'], 'source': {'kind': 'current release'}}
entries[105]={'legacyVersion': 105, 'version': 'v0.0.105', 'date': '2026-10-28', 'title': 'I improved graphics, fog and space navigation', 'changes': ['I added Ultra and Ultra+ with denser scenery, more clouds and stars, higher resolution budgets, sharper images and higher-quality shadows.', 'I fixed empty-space clicks locking invisible bodies.', 'I made airless-world fog dark gray and based its fade on distance so it stays steady while looking around.', 'I added a 100 RC confirmation before entering Free Camera. Canceling does not spend anything.', 'I fixed system-to-system warp prices at 1000 FP plus 5–10 RC depending on the destination’s distance from Sol, including repeat visits. Earth return stays free.', 'I made Settings the only menu that pauses the simulation. Other menus and confirmations keep the world running.', 'I kept the locked destination label visible across systems, with a screen-edge marker when needed and distance in Ly. Intersystem bearings and distances follow the schematic game map.'], 'source': {'kind': 'current release'}}
entries[106]={'legacyVersion': 106, 'version': 'v0.0.106', 'date': '2026-10-28', 'title': 'I fixed graphics choices and mining sign-in interruptions', 'changes': ['I removed screen-edge labels for locked destinations. Their normal labels still appear when they are in view.', 'I added a visible Graphics quality dropdown with Low, Medium, High, Ultra and Ultra+. Older cached page layouts are repaired when the current game loads.', 'I stopped inventory validation and connection errors from reopening the sign-in screen. Unsaved changes stay pending, and real account/session errors still require sign-in.', 'I prepared a server catalogue update for every current solid body and item. Cloud saves from newer bodies still need that database update applied.'], 'source': {'kind': 'current release'}}
entries[107]={'legacyVersion': 107, 'version': 'v0.0.107', 'date': '2026-10-28', 'title': 'I added guest play, a beginner guide and account rewards', 'changes': ['I added Play as Guest. Guests can explore, fly, land, mine, craft and sell with temporary progress, read Global Chat and view public profiles. Signing in loads account progress without refreshing.', 'I added a short PC and mobile tutorial, a Skip option, Replay Tutorial in Settings and optional beginner tips. Account tutorial completion is saved; guest completion lasts only for the current page session.', 'I added daily rewards from 100 FP to 500 FP, with 10 RC on Day 7. The cycle repeats after seven claims and refreshes at midnight UTC.', 'New accounts receive a one-time welcome gift of 250 FP and 5 RC. Existing accounts keep their balances and do not receive this new-account gift.', 'I added discovery marks to Universe Map and aggregate player statistics to the developer menu.', 'I reduced startup asset preloading and stopped hidden Universe Map thumbnails from requesting textures. All five graphics modes and existing world effects remain available.'], 'source': {'kind': 'current release'}}
entries[108]={'legacyVersion': 108, 'version': 'v0.0.108', 'date': '2026-10-28', 'title': 'I improved guest menus, tutorial saves and daily supplies', 'changes': ['I save fully completed tutorials and retry interrupted account syncs. Skip leaves the tutorial available for next time. Guest tutorial preferences are remembered on this device.', 'I moved the Guest label below the top-right buttons and kept the account button icon-only. Guest account, friends and reward menus explain each feature and close with an X.', 'I added public Online/Offline status and refreshed player profiles, plus Guest Mode help.', 'I moved Daily Rewards to a gift icon left of Global Chat, with a ready badge and one message sound per available daily reward.', 'I centered and compacted the reward menu, added currency/item icons, and added building supplies throughout the week, including 64 TNT on Day 7. Server claims remain atomic and safe to retry.'], 'source': {'kind': 'current release'}}
entries[109]={'legacyVersion': 109, 'version': 'v0.0.109', 'date': '2026-10-28', 'title': 'I made menus compact and fixed portrait controls', 'changes': ['I added separate Menu Size settings for Account, Party, Global Chat, Daily Rewards, Update Logs and Universe Map, with smaller defaults and saved device preferences.', 'I separated Run Button Size from Jump Button Size, matched the Gift and Global Chat icons, and spaced Guest, Continue and sign-in actions.', 'I gave portrait mode compact HUD and separate steering, thrust and speed-gauge areas, and refresh the canvas after orientation/fullscreen/viewport changes.'], 'source': {'kind': 'current release'}}
entries[110]={'legacyVersion': 110, 'version': 'v0.0.110', 'date': '2026-10-28', 'title': 'I improved graphics and atmospheric flight', 'changes': ['I added 2,500m solid-world atmospheres, a 200 m/s upper band and a 450 m/s lower maximum with smooth cap transitions. Entry and exit retain control and momentum.', 'I added airflow-facing plasma, wind and subtle camera shake. Plasma peaks at 1,500–1,000m, fades to 800m and stays off below it. Exit effects are weaker, and reentry causes no damage.', 'I require atmospheric ships to descend below 800m before Land can engage. Airless landing remains available.', 'I added white wingtip trails in space, longer and brighter while boosting, with an independent saved Settings toggle. The ship model is unchanged.', 'I added planet micro-relief, sharper map sampling, soft cloud billows, star twinkle, richer black-hole bands and Ultra highlight/shadow improvements, with bounded mobile/Low budgets.'], 'source': {'kind': 'current release'}}
for entry in entries.values():
 entry['changes']=[re.sub(r"Applee[’']s\s*",'my ',text) for text in entry['changes']]
 entry['title']=re.sub(r'\bv(\d+)\b',r'v0.0.\1',re.sub(r"Applee[’']s\s*",'My ',entry['title']))
entries[111]={'legacyVersion': 111, 'version': 'v0.0.111', 'date': '2026-10-29', 'title': 'I extended atmospheres and improved reentry', 'changes': ['I extended atmospheric flight to 5,000m, faded the sky by 3,000m and blended terrain into a spherical planet visible from 4,000m.', 'I set entry speed to 50 m/s and the upper atmosphere cap to 100 m/s, with a 450 m/s lower maximum and smooth cap transitions. Landing still requires descending below 800m.', 'I added orange-red airflow-facing heat shields, animated plasma, sparks and fiery streaks. Reentry peaks at 1,500–1,000m, fades to 800m and causes no damage.', 'I smoothed reentry and weaker ascent shake across all ship cameras, preserving rotation and zoom.', 'I added subtle heat distortion on High and above, richer Ultra/Ultra+ glow, bounded mobile particle budgets and preserved white space wing trails.'], 'source': {'kind': 'current release'}}
entries[112]={'legacyVersion': 112, 'version': 'v0.0.112', 'date': '2026-10-29', 'title': 'I fixed loading stuck at zero', 'changes': ['I let Guest and successful login continue loading immediately while slow account connection checks finish independently. Late account responses cannot replace the selected mode.', 'I show manifest loading progress immediately and display a Retry button if the loader itself cannot load, without clearing saved progress.'], 'source': {'kind': 'current release'}}
entries[113]={'legacyVersion': 113, 'version': 'v0.0.113', 'date': '2026-10-29', 'title': 'I fixed the nearby Earth transition and intensified reentry', 'changes': ['I moved the terrain-to-planet blend to 4,000–5,000m while keeping the sky fade complete by 3,000m.', 'I enlarged the near-planet horizon and matched the space boundary so Earth remains close at atmospheric exit. An opaque ground shell seals terrain gaps during the blend.', 'I intensified airflow-facing plasma, added a compressed bow shock on desktop Ultra/Ultra+, lengthened fiery streaks and added turbulent ember movement. Low/Medium and mobile retain bounded effects.', 'I made reentry shake roughly four times stronger on PC, with stronger mobile shake, while retaining smooth fades and independent camera rotation and zoom.'], 'source': {'kind': 'current release'}}
entries[114]={'legacyVersion': 114, 'version': 'v0.0.114', 'date': '2026-10-29', 'title': 'I unified atmospheric fog and the planet transition', 'changes': ['I made the globe and opaque ground shell obey the same distance fog as terrain, so they cannot bypass fog layers.', 'I added shared spherical atmospheric extinction and haze to surface and space planet rendering. Lower atmosphere remains visible when looking downward, even after the overhead sky darkens.', 'I replaced the early black fog tint and abrupt horizon clearing with continuous altitude-dependent fog ranges and a horizon that fades with the 4,000–5,000m terrain transition.', 'I removed the unfogged legacy atmosphere halo and matched haze colors, weather density and physical scale across local and space rendering. Mobile uses fewer atmospheric samples.'], 'source': {'kind': 'current release'}}
data={'currentVersion':'v0.0.114','legacyMapping':'Legacy source N is displayed as v0.0.N.','historyNote':'The earliest separately documented release is v0.0.3. Original creation notes and separate entries for v0.0.1–v0.0.2, v0.0.9–v0.0.13 and v0.0.18–v0.0.22 are not recoverable from this repository. The first Git import on 25 October 2026 already contained earlier development. Historical features may be replaced by later updates.','entries':sorted(entries.values(),key=lambda e:e['legacyVersion'],reverse=True)}
(root/'public/update-history.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(len(entries),'documented releases, earliest',min(entries))
